<?php
declare(strict_types=1);
$brandName=is_string($brandName??null)?$brandName:'Talyvane';$mode=is_string($mode??null)?$mode:'assigned';$error=is_string($error??null)?$error:'';$csrf=is_string($csrf??null)?$csrf:'';$items=is_array($items??null)?$items:[];$specialists=is_array($specialists??null)?$specialists:[];$case=is_array($case??null)?$case:[];$escape=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Safeguarding · <?=$escape($brandName)?></title><style>body{margin:0;background:#f3f2ed;color:#1a2939;font:15px/1.6 system-ui}main{max-width:1000px;margin:35px auto;padding:18px}.panel{background:white;border:1px solid #ddd;padding:20px;margin:18px 0}.field{display:grid;gap:6px;margin:13px 0}input,select,textarea{font:inherit;padding:10px;border:1px solid #bbc4cd;width:100%;box-sizing:border-box}.button{background:#17283a;color:white;border:0;padding:11px 16px}.error{background:#fff0ee;padding:12px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #ddd}</style><body><header class="panel"><?=$escape($brandName)?> · <a href="/admin">Administration</a></header><main><p>RESTRICTED SAFEGUARDING · NOT AN EMERGENCY SERVICE</p><?php if($error!==''):?><p class="error"><?=$escape($error)?></p><?php endif;?>
<?php if($mode==='report'):?><h1>Submit confidential report</h1><p>Reporter access ends at acknowledgement. Do not include identity-document numbers, full birth dates, passwords, payment secrets or raw evidence.</p><form class="panel" method="post" action="/admin/safeguarding/reports"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><div class="field"><label>Category</label><select name="category"><?php foreach(['safety_concern','exploitation','coercion','trafficking','minor_safety','harassment','violence','wellbeing','other'] as $v):?><option value="<?=$escape($v)?>"><?=$escape($v)?></option><?php endforeach;?></select></div><div class="field"><label>Severity</label><select name="severity"><?php foreach(['low','medium','high','critical'] as $v):?><option><?=$escape($v)?></option><?php endforeach;?></select></div><div class="field"><label>Opaque related record reference</label><input name="subject_reference" maxlength="1000"></div><div class="field"><label>Summary</label><input name="summary" minlength="10" maxlength="1000" required></div><div class="field"><label>Details</label><textarea name="details" minlength="20" maxlength="10000" required></textarea></div><div class="field"><label>Assigned safeguarding specialist</label><select name="specialist_id" required><?php foreach($specialists as $s):?><option value="<?=$escape($s['id'])?>"><?=$escape($s['email'])?></option><?php endforeach;?></select></div><button class="button">Submit report</button></form>
<?php elseif($mode==='acknowledgement'):?><h1>Report received</h1><section class="panel">Case reference: <strong><?=$escape($caseReference??'')?></strong><p>Case contents are restricted to the assigned specialist. This is not an emergency hotline.</p></section>
<?php elseif($mode==='detail'):?><h1><?=$escape($case['case_reference']??'Case')?></h1><section class="panel"><p><?=$escape($case['category']??'')?> · <?=$escape($case['severity']??'')?> · <?=$escape($case['status']??'')?></p><h2><?=$escape($case['summary']??'')?></h2><p><?=nl2br($escape($case['details']??''))?></p><p>Related record: <?=$escape($case['subject_reference']??'')?></p></section><form class="panel" method="post" action="/admin/safeguarding/cases/<?=$escape($case['id'])?>/transition"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><select name="status"><?php foreach(['triaged','investigating','action_required','resolved','closed'] as $v):?><option><?=$escape($v)?></option><?php endforeach;?></select><textarea name="reason" minlength="10" maxlength="1000" required placeholder="Reason for transition"></textarea><button class="button">Record transition</button></form><?php foreach(($case['events']??[]) as $event):?><p><?=$escape($event['event_key'])?> · <?=$escape($event['created_at'])?> — <?=$escape($event['note']??'')?></p><?php endforeach;?>
<?php elseif($mode==='governance'):?><h1>Safeguarding governance · metadata only</h1><section class="panel"><table><thead><tr><th>Reference</th><th>Category</th><th>Status</th><th>Legal hold</th><th>Action</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=$escape($item['case_reference'])?></td><td><?=$escape($item['category'])?> · <?=$escape($item['severity'])?></td><td><?=$escape($item['status'])?></td><td><?=(int)$item['legal_hold']?'Active':'None'?></td><td><?php if((int)$item['legal_hold']):?><form method="post" action="/admin/safeguarding/governance/<?=$escape($item['id'])?>/release"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><input name="reason" minlength="20" maxlength="1000" required><button class="button">Release hold</button></form><?php else:?><form method="post" action="/admin/safeguarding/governance/<?=$escape($item['id'])?>/hold"><input type="hidden" name="_csrf" value="<?=$escape($csrf)?>"><input name="reason" minlength="20" maxlength="1000" required><button class="button">Place hold</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<?php else:?><h1>Assigned safeguarding cases</h1><section class="panel"><table><thead><tr><th>Reference</th><th>Category</th><th>Severity</th><th>Status</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><a href="/admin/safeguarding/cases/<?=$escape($item['id'])?>"><?=$escape($item['case_reference'])?></a></td><td><?=$escape($item['category'])?></td><td><?=$escape($item['severity'])?></td><td><?=$escape($item['status'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?></main></body></html>
